<?php
declare(strict_types=1);
require_once __DIR__ . '/../vendors/vendor_guard.php';
if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);exit('Method not allowed.');}
if(!cnrbyte_auth_csrf_valid($_POST['csrf_token']??null)){http_response_code(403);exit('Invalid or expired form token.');}
$vendorId=(int)$_SESSION['vendor_info']['id'];$clientId=(int)($_SESSION['user_info']['id']??0);$recipientId=filter_var($_POST['client_id']??null,FILTER_VALIDATE_INT);$body=trim((string)($_POST['body']??''));$subject=trim((string)($_POST['subject']??'Business enquiry'));
if(!$recipientId||$recipientId<1||$body===''||mb_strlen($body)>5000||mb_strlen($subject)>180){$_SESSION['errors_create']=['message'=>'Select a customer and enter a message of up to 5,000 characters.'];header('Location: /cnrbyte/messages/vendor_chat.pge.php');exit;}
$stmt=$conn->prepare('SELECT c.id FROM clients c WHERE c.id=? AND EXISTS (SELECT 1 FROM marketplace_orders mo WHERE mo.vendor_id=? AND mo.buyer_id=c.id) LIMIT 1');$stmt->bind_param('ii',$recipientId,$vendorId);$stmt->execute();$customerExists=(bool)$stmt->get_result()->fetch_assoc();$stmt->close();if(!$customerExists){http_response_code(403);exit('This customer is not associated with your business.');}
$key='direct:v'.$vendorId.':c'.$recipientId;$senderType='vendor';$recipientType='client';
$conn->begin_transaction();try{$stmt=$conn->prepare('INSERT INTO cnrbyte_messages (conversation_key,sender_type,sender_id,recipient_type,recipient_id,subject,body) VALUES (?,?,?,?,?,?,?)');$stmt->bind_param('ssissss',$key,$senderType,$vendorId,$recipientType,$recipientId,$subject,$body);$stmt->execute();$stmt->close();$title='New business message';$note='A business sent you a direct message.';$target='/cnrbyte/messages/chat.pge.php?vendor_id='.$vendorId;$kind='message';$stmt=$conn->prepare('INSERT INTO cnrbyte_notifications (recipient_type,recipient_id,notification_type,title,message,target_url) VALUES (?,?,?,?,?,?)');$stmt->bind_param('sissss',$recipientType,$recipientId,$kind,$title,$note,$target);$stmt->execute();$stmt->close();$conn->commit();}catch(Throwable $e){try{$conn->rollback();}catch(Throwable $ignored){}error_log('CnrByte vendor direct message failed: '.$e->getMessage());$_SESSION['errors_create']=['message'=>'The message could not be sent. Confirm that the Step 13 messaging migration has been applied.'];}
header('Location: /cnrbyte/messages/vendor_chat.pge.php?client_id='.$recipientId);exit;
